        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    # Try until we produce a nontrivial, valid instance
    for _ in range(1000):
        num_circles = rng.randint(60, 120)  # fairly large to avoid trivial patterns
        start_radius = rng.randint(1, 9)
        step = rng.randint(1, 7)
        weight_power = rng.randint(1, 4)  # ensure not the plain area (p=0)
        exponent = weight_power + 2
        red_run = rng.randint(1, 4)
        green_run = rng.randint(1, 4)
        # Avoid the trivial strict alternation with plain area and too few blocks
        if red_run == 1 and green_run == 1:
            continue
        # Compute number of green blocks that actually occur
        # Green blocks start at k = red_run + j*(red_run+green_run), j >= 0, up to num_circles
        total_blocks = 0
        j = 0
        while True:
            s = red_run + j*(red_run + green_run)
            if s > num_circles:
                break
            total_blocks += 1
            j += 1
        if total_blocks < 2:
            continue  # enforce multiple green blocks for difficulty
        # Compute weighted green mass via block endpoints and check nontrivial ratio
        def Rk(k):
            return start_radius + k*step
        def Wk(k):
            return pow(Rk(k), exponent)
        N = 0
        j = 0
        while True:
            s = red_run + j*(red_run + green_run)
            if s > num_circles:
                break
            e = min(num_circles, s + green_run - 1)
            N += Wk(e) - Wk(s-1)
            j += 1
        D = Wk(num_circles)
        # Sanity checks: positive masses and ratio not exactly 1/2
        if N <= 0 or D <= 0:
            continue
        # Reduce and test nontriviality
        g = math.gcd(N, D)
        m = N // g
        n = D // g
        if m*2 == n:  # avoid exact 1/2
            continue
        return {
            'num_circles': num_circles,
            'start_radius': start_radius,
            'step': step,
            'weight_power': weight_power,
            'exponent': exponent,
            'red_run': red_run,
            'green_run': green_run
        }
    # Fallback deterministic instance if random attempts fail (extremely unlikely)
    num_circles = 80
    start_radius = 3
    step = 4
    weight_power = 2
    exponent = weight_power + 2
    red_run = 2
    green_run = 3
    return {
        'num_circles': num_circles,
        'start_radius': start_radius,
        'step': step,
        'weight_power': weight_power,
        'exponent': exponent,
        'red_run': red_run,
        'green_run': green_run
    }

